package sprint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/project"
)

const (
	runtimeMetricsSchemaVersion = 1
	runtimeMetricsFileName      = ".runtime-metrics.json"
	maxRuntimeMetricRecords     = 512
)

type RuntimeTokenMetric struct {
	Known bool  `json:"known"`
	Value int64 `json:"value,omitempty"`
}

type SprintRuntimeMetric struct {
	Stage              PlanningStage      `json:"stage"`
	Operation          string             `json:"operation,omitempty"`
	Task               string             `json:"task,omitempty"`
	Coverage           string             `json:"coverage,omitempty"`
	RunID              string             `json:"run_id,omitempty"`
	SessionID          string             `json:"session_id,omitempty"`
	Status             string             `json:"status,omitempty"`
	Provider           string             `json:"provider,omitempty"`
	Model              string             `json:"model,omitempty"`
	PromptBytes        int                `json:"prompt_bytes"`
	SharedPrefixBytes  int                `json:"shared_prefix_bytes,omitempty"`
	StageSuffixBytes   int                `json:"stage_suffix_bytes"`
	SharedPrefixDigest string             `json:"shared_prefix_sha256,omitempty"`
	CacheKey           string             `json:"cache_key,omitempty"`
	InputTokens        RuntimeTokenMetric `json:"input_tokens"`
	OutputTokens       RuntimeTokenMetric `json:"output_tokens"`
	ReasoningTokens    RuntimeTokenMetric `json:"reasoning_tokens"`
	CacheReadTokens    RuntimeTokenMetric `json:"cache_read_tokens"`
	CacheWriteTokens   RuntimeTokenMetric `json:"cache_write_tokens"`
	TotalTokens        RuntimeTokenMetric `json:"total_tokens"`
	Turns              RuntimeTokenMetric `json:"turns"`
	CostAmount         float64            `json:"cost_amount,omitempty"`
	CostCurrency       string             `json:"cost_currency,omitempty"`
	CostEstimated      bool               `json:"cost_estimated,omitempty"`
	CostSource         string             `json:"cost_source,omitempty"`
	StartedAt          time.Time          `json:"started_at,omitempty"`
	FinishedAt         time.Time          `json:"finished_at,omitempty"`
	ErrorCategory      string             `json:"error_category,omitempty"`
}

type SprintRuntimeMetrics struct {
	SchemaVersion int                   `json:"schema_version"`
	Project       string                `json:"project"`
	Sprint        string                `json:"sprint"`
	UpdatedAt     time.Time             `json:"updated_at"`
	Runs          []SprintRuntimeMetric `json:"runs"`
}

func RuntimeMetricsRelPath(sp Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug, runtimeMetricsFileName))
}

func LoadRuntimeMetrics(root string, sp Sprint) (SprintRuntimeMetrics, error) {
	path, err := resolveSprintContained(root, sp, RuntimeMetricsRelPath(sp))
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	var metrics SprintRuntimeMetrics
	if err := json.Unmarshal(data, &metrics); err != nil {
		return SprintRuntimeMetrics{}, fmt.Errorf("decode sprint runtime metrics: %w", err)
	}
	if metrics.SchemaVersion != runtimeMetricsSchemaVersion || metrics.Project != sp.Project || metrics.Sprint != sp.Slug {
		return SprintRuntimeMetrics{}, fmt.Errorf("invalid sprint runtime metrics identity")
	}
	return metrics, nil
}

func (s Service) RuntimeMetrics(projectRef, sprintRef string) (SprintRuntimeMetrics, error) {
	projects, err := project.DiscoverProjects(s.root)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	p, err := project.ResolveProject(projects, projectRef)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	sprints, err := DiscoverSprints(s.root, p)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	sp, err := ResolveSprint(sprints, sprintRef)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	if !inside(p.Path, sp.Path) {
		return SprintRuntimeMetrics{}, fmt.Errorf("sprint path mismatch for %q", sp.Slug)
	}
	metrics, err := LoadRuntimeMetrics(s.root, sp)
	if errors.Is(err, os.ErrNotExist) {
		return SprintRuntimeMetrics{SchemaVersion: runtimeMetricsSchemaVersion, Project: sp.Project, Sprint: sp.Slug}, nil
	}
	return metrics, err
}

func (s Service) startSprintRuntime(ctx context.Context, sp Sprint, stage PlanningStage, req pruntime.Request) (pruntime.Result, error) {
	// Retry cleanup that was interrupted by a crash before admitting more work.
	// Recent failed stores remain available for session recovery.
	pruntime.CleanupRuntimeStores(sp.Path, 72*time.Hour, 2*1024*1024*1024, false)
	result, runErr := s.runtime.StartRun(ctx, req)
	if metricErr := s.recordRuntimeMetric(sp, stage, req, result); metricErr != nil {
		result.Warnings = append(result.Warnings, "runtime metrics were not persisted: "+safeError(metricErr))
	}
	return result, runErr
}

func (s Service) recordRuntimeMetric(sp Sprint, stage PlanningStage, req pruntime.Request, result pruntime.Result) error {
	if s.metricsMu != nil {
		s.metricsMu.Lock()
		defer s.metricsMu.Unlock()
	}
	metrics, err := LoadRuntimeMetrics(s.root, sp)
	if errors.Is(err, os.ErrNotExist) {
		metrics = SprintRuntimeMetrics{SchemaVersion: runtimeMetricsSchemaVersion, Project: sp.Project, Sprint: sp.Slug}
	} else if err != nil {
		return err
	}
	explanation := explainComposedPrompt(req.Prompt)
	record := SprintRuntimeMetric{
		Stage: stage, Operation: req.Metadata["operation"], Task: req.Metadata["task"], Coverage: req.Metadata["coverage"],
		RunID: result.RunID, SessionID: result.SessionID, Status: result.Status, Provider: req.Provider, Model: req.Model,
		PromptBytes: explanation.TotalBytes, SharedPrefixBytes: explanation.SharedPrefixBytes, StageSuffixBytes: explanation.StageSuffixBytes,
		SharedPrefixDigest: explanation.SharedPrefixDigest, CacheKey: explanation.CacheKey,
		InputTokens: metricToken(result.Usage.InputTokensKnown, result.Usage.InputTokens), OutputTokens: metricToken(result.Usage.OutputTokensKnown, result.Usage.OutputTokens),
		ReasoningTokens: metricToken(result.Usage.ReasoningTokensKnown, result.Usage.ReasoningTokens), CacheReadTokens: metricToken(result.Usage.CacheReadTokensKnown, result.Usage.CacheReadTokens),
		CacheWriteTokens: metricToken(result.Usage.CacheWriteTokensKnown, result.Usage.CacheWriteTokens), TotalTokens: metricToken(result.Usage.TotalTokensKnown, result.Usage.TotalTokens),
		Turns: metricToken(result.Usage.TurnsKnown, result.Usage.Turns), StartedAt: result.StartedAt, FinishedAt: result.FinishedAt,
	}
	if result.EstimatedCost != nil {
		record.CostAmount, record.CostCurrency, record.CostEstimated = result.EstimatedCost.Amount, result.EstimatedCost.Currency, result.EstimatedCost.Estimate
		record.CostSource = result.EstimatedCost.Source
	}
	if result.Error != nil {
		record.ErrorCategory = result.Error.Category
	}
	metrics.Runs = append(metrics.Runs, record)
	if len(metrics.Runs) > maxRuntimeMetricRecords {
		metrics.Runs = append([]SprintRuntimeMetric(nil), metrics.Runs[len(metrics.Runs)-maxRuntimeMetricRecords:]...)
	}
	metrics.UpdatedAt = s.now().UTC()
	data, err := json.MarshalIndent(metrics, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	path, err := resolveSprintContained(s.root, sp, RuntimeMetricsRelPath(sp))
	if err != nil {
		return err
	}
	return atomicWriteFile(path, data)
}

func metricToken(known bool, value int64) RuntimeTokenMetric {
	return RuntimeTokenMetric{Known: known, Value: value}
}

package sprint

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"syscall"
	"time"
)

type verificationLockInfo struct {
	Project    string    `json:"project"`
	Sprint     string    `json:"sprint"`
	PID        int       `json:"pid"`
	AcquiredAt time.Time `json:"acquiredAt"`
}

type verificationFileLock struct {
	path string
	info verificationLockInfo
}

func acquireVerificationFileLock(root string, sprint Sprint, now time.Time) (*verificationFileLock, error) {
	path := filepath.Join(root, ".ultraplan", "locks", "sprint", sprint.Project+"--"+sprint.Slug+".lock")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return nil, fmt.Errorf("create verification lock directory: %w", err)
	}
	info := verificationLockInfo{Project: sprint.Project, Sprint: sprint.Slug, PID: os.Getpid(), AcquiredAt: now.UTC()}
	for attempt := 0; attempt < 2; attempt++ {
		file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
		if err == nil {
			data, marshalErr := json.Marshal(info)
			if marshalErr == nil {
				_, marshalErr = file.Write(append(data, '\n'))
			}
			closeErr := file.Close()
			if marshalErr != nil || closeErr != nil {
				_ = os.Remove(path)
				return nil, errors.Join(marshalErr, closeErr)
			}
			return &verificationFileLock{path: path, info: info}, nil
		}
		if !errors.Is(err, fs.ErrExist) {
			return nil, fmt.Errorf("create verification lock: %w", err)
		}
		existing, readErr := readVerificationFileLock(path)
		if readErr != nil {
			return nil, fmt.Errorf("%w: unreadable lock %s: %v", ErrVerificationConflict, path, readErr)
		}
		if verificationProcessAlive(existing.PID) {
			return nil, fmt.Errorf("%w for %s/%s; pid %d has owned the attempt since %s", ErrVerificationConflict, sprint.Project, sprint.Slug, existing.PID, existing.AcquiredAt.Format(time.RFC3339))
		}
		if removeErr := os.Remove(path); removeErr != nil && !errors.Is(removeErr, fs.ErrNotExist) {
			return nil, fmt.Errorf("remove stale verification lock: %w", removeErr)
		}
	}
	return nil, fmt.Errorf("%w for %s/%s", ErrVerificationConflict, sprint.Project, sprint.Slug)
}

func readVerificationFileLock(path string) (verificationLockInfo, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return verificationLockInfo{}, err
	}
	var info verificationLockInfo
	if err := json.Unmarshal(data, &info); err != nil {
		return verificationLockInfo{}, err
	}
	if info.PID <= 0 || info.Project == "" || info.Sprint == "" || info.AcquiredAt.IsZero() {
		return verificationLockInfo{}, fmt.Errorf("invalid lock identity")
	}
	return info, nil
}

func (lock *verificationFileLock) release() error {
	if lock == nil {
		return nil
	}
	current, err := readVerificationFileLock(lock.path)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	if current.PID != lock.info.PID || current.Project != lock.info.Project || current.Sprint != lock.info.Sprint || !current.AcquiredAt.Equal(lock.info.AcquiredAt) {
		return fmt.Errorf("verification lock ownership changed; refusing release")
	}
	return os.Remove(lock.path)
}

func verificationProcessAlive(pid int) bool {
	if pid <= 0 {
		return false
	}
	err := syscall.Kill(pid, 0)
	return err == nil || errors.Is(err, syscall.EPERM)
}

package sprint

import (
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/project"
)

func ValidateSprintIndexContent(content string, catalog project.ProjectIndex) (SprintIndex, []ValidationFinding) {
	index, findings := ParseSprintIndex(content)
	findings = append(findings, validateSubset(index.Contracts, catalog, project.SectionActiveContractPool, "Selected Contracts")...)
	findings = append(findings, validateSubset(index.EvidenceReports, catalog, project.SectionAvailableEvidenceReports, "Selected Evidence Reports")...)
	findings = append(findings, validateReasoningTemplates(index.ReasoningTemplates, catalog)...)
	findings = append(findings, validateSubset(index.ReviewProtocols, catalog, project.SectionReviewProtocols, "Required Review Protocols")...)
	findings = append(findings, validateExcluded(index.ExcludedContexts)...)
	sortSprintFindings(findings)
	return index, findings
}

func validateSubset(items []SelectedItem, catalog project.ProjectIndex, section project.CatalogSection, label string) []ValidationFinding {
	var findings []ValidationFinding
	for _, item := range items {
		var byName []project.CatalogEntry
		for _, entry := range catalog.Entries {
			if entry.Section == section && strings.EqualFold(entry.Name, item.Name) {
				byName = append(byName, entry)
			}
		}
		if len(byName) == 0 {
			findings = append(findings, finding(label, item.Name, item.Path, "selected entry not in project index", "no catalog entry with this name exists in the required section", "Select an entry listed in project-index.md."))
			continue
		}
		if item.Path == "" || section == project.SectionActiveContractPool {
			continue
		}
		foundPath := false
		for _, entry := range byName {
			if entry.Path == item.Path {
				foundPath = true
				break
			}
		}
		if !foundPath {
			findings = append(findings, finding(label, item.Name, item.Path, "selected path does not match project index", "catalog entry name exists but with a different path", "Use the exact path from project-index.md."))
		}
	}
	return findings
}

func validateReasoningTemplates(items []SelectedItem, catalog project.ProjectIndex) []ValidationFinding {
	var findings []ValidationFinding
	for _, item := range items {
		foundName := false
		for _, entry := range catalog.Entries {
			if entry.Section == project.SectionAvailableReasoningTemplate && strings.EqualFold(entry.Name, item.Name) {
				foundName = true
				break
			}
		}
		if !foundName {
			findings = append(findings, finding("Selected Reasoning Templates", item.Name, item.Path, "selected entry not in project index", "no catalog entry with this template name exists", "Select a reasoning template listed in project-index.md."))
			continue
		}
		if item.Path == "" {
			findings = append(findings, finding("Selected Reasoning Templates", item.Name, item.Path, "missing output path", "reasoning template selection must name its sprint output path", "Set Output Path to a workspace-relative sprint reasoning file."))
			continue
		}
		if strings.HasPrefix(item.Path, "/") || strings.Contains(item.Path, "\x00") || strings.Contains(item.Path, "..") {
			findings = append(findings, finding("Selected Reasoning Templates", item.Name, item.Path, "unsafe output path", "output path must be workspace-relative and contained in the sprint", "Use a workspace-relative path under the sprint reasoning directory."))
		}
	}
	return findings
}

func validateExcluded(items []SelectedItem) []ValidationFinding {
	if len(items) == 0 {
		return []ValidationFinding{finding("Excluded Context", "", "", "missing excluded context", "no out-of-scope behavior was recorded", "List excluded context so later stages do not infer extra scope.")}
	}
	needles := []string{"implementation", "smoke", "review", "issue", "git"}
	seen := map[string]bool{}
	for _, item := range items {
		text := strings.ToLower(item.Name + " " + item.Why)
		for _, needle := range needles {
			if strings.Contains(text, needle) {
				seen[needle] = true
			}
		}
	}
	var findings []ValidationFinding
	for _, needle := range needles {
		if !seen[needle] {
			findings = append(findings, finding("Excluded Context", needle, "", "required excluded context not recorded", "known Phase 2 non-goal is not mentioned", "Record the deferred behavior in Excluded Context."))
		}
	}
	return findings
}

